function ScrollCue() {
  return (
    <div
      className="jalwa-scroll-cue"
      style={{
        position: "absolute", bottom: "4vh", left: "50%", transform: "translateX(-50%)",
        display: "flex", flexDirection: "column", alignItems: "center", gap: 4,
      }}
    >
      <span style={{
        fontFamily: "'Poppins', sans-serif", fontSize: 11, letterSpacing: "0.16em",
        textTransform: "uppercase", color: "#3f6b4f", opacity: 0.75,
      }}>
        Scroll
      </span>
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#3f6b4f" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M6 9l6 6 6-6" />
      </svg>
    </div>
  );
}

function DetailRow({ label, value, icon }) {
  return (
    <div style={{ display: "flex", alignItems: "flex-start", gap: 14, textAlign: "left", padding: "10px 0", borderTop: "1px solid rgba(201,161,90,0.18)" }}>
      <svg style={{ width: 20, height: 20, flexShrink: 0, marginTop: 2 }} viewBox="0 0 24 24" fill="none" stroke="#3f6b4f" strokeWidth="1.6">
        {icon}
      </svg>
      <div>
        <div style={{ fontSize: 11, letterSpacing: "0.1em", textTransform: "uppercase", color: "#8a6a2f", opacity: 0.85 }}>{label}</div>
        <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(16px,2.2vw,19px)", color: "#22391f" }}>{value}</div>
      </div>
    </div>
  );
}